import { describe, expect, it } from "vitest"
import {
  extractHostnamesFromConfig,
  HostnameMiddlewareOptions,
  hydrateGeneratedConfig,
} from "./generated-config"

const header = `// This file is auto-generated by @appwarden/build-cloudflare-action
// Do not edit manually

`

describe("generated-config", () => {
  describe("hydrateGeneratedConfig", () => {
    it("should map a fully populated hostname to the middleware config shape", () => {
      const middlewareOptionsMap = new Map<string, HostnameMiddlewareOptions>([
        [
          "app.example.com",
          {
            debug: false,
            "bypass-paths": ["/health", "/api/health"],
            website: {
              "lock-page-slug": "/maintenance",
              "csp-mode": "report-only",
              "csp-directives": { "script-src": ["self", "{{nonce}}"] },
            },
            api: {
              "base-paths": ["/api"],
              response: {
                status: 521,
                body: '{"error":"Service unavailable","source":"appwarden"}',
                headers: [
                  { name: "content-type", value: "application/json" },
                  { name: "x-appwarden-lock", value: "api" },
                ],
              },
            },
          },
        ],
      ])

      const { config, hostnames, debug } =
        hydrateGeneratedConfig(middlewareOptionsMap)

      expect(config).toEqual({
        "app.example.com": {
          debug: false,
          bypassPaths: ["/health", "/api/health"],
          website: {
            lockPageSlug: "/maintenance",
            cspMode: "report-only",
            cspDirectives: { "script-src": ["self", "{{nonce}}"] },
          },
          api: {
            basePaths: ["/api"],
            response: {
              status: 521,
              body: '{"error":"Service unavailable","source":"appwarden"}',
              headers: [
                { name: "content-type", value: "application/json" },
                { name: "x-appwarden-lock", value: "api" },
              ],
            },
          },
        },
      })
      expect(hostnames).toEqual(["app.example.com"])
      expect(debug).toBe(false)
    })

    it("should serialise the config into the generated module", () => {
      const middlewareOptionsMap = new Map<string, HostnameMiddlewareOptions>([
        [
          "app.example.com",
          {
            website: {
              "lock-page-slug": "/maintenance",
              "csp-mode": "enforced",
              "csp-directives": { "default-src": "'self'" },
            },
          },
        ],
      ])

      const { configString } = hydrateGeneratedConfig(middlewareOptionsMap)

      expect(configString).toBe(`${header}export const config = {
  "app.example.com": {
    "website": {
      "lockPageSlug": "/maintenance",
      "cspMode": "enforced",
      "cspDirectives": {
        "default-src": "'self'"
      }
    }
  }
}
`)
    })

    it("should generate config for multiple hostnames", () => {
      const middlewareOptionsMap = new Map<string, HostnameMiddlewareOptions>([
        [
          "app.example.com",
          {
            "bypass-paths": ["/health"],
            website: { "lock-page-slug": "/maintenance" },
          },
        ],
        [
          "staging.example.com",
          {
            website: {
              "lock-page-slug": "/staging-maintenance",
              "csp-mode": "report-only",
            },
          },
        ],
      ])

      const { config, hostnames } = hydrateGeneratedConfig(middlewareOptionsMap)

      expect(config["app.example.com"].bypassPaths).toEqual(["/health"])
      expect(config["app.example.com"].website).toEqual({
        lockPageSlug: "/maintenance",
      })
      expect(config["staging.example.com"].website).toEqual({
        lockPageSlug: "/staging-maintenance",
        cspMode: "report-only",
      })
      expect(hostnames).toEqual(["app.example.com", "staging.example.com"])
    })

    it("should omit empty nested groups", () => {
      const middlewareOptionsMap = new Map<string, HostnameMiddlewareOptions>([
        [
          "app.example.com",
          {
            website: { "lock-page-slug": "/maintenance" },
            api: {},
          },
        ],
      ])

      const { config } = hydrateGeneratedConfig(middlewareOptionsMap)

      expect(config["app.example.com"]).toEqual({
        website: { lockPageSlug: "/maintenance" },
      })
    })

    it("should generate empty config when a hostname has no options", () => {
      const middlewareOptionsMap = new Map<string, HostnameMiddlewareOptions>([
        ["app.example.com", {}],
      ])

      const result = hydrateGeneratedConfig(middlewareOptionsMap)

      expect(result.configString).toBe(`${header}export const config = {}
`)
      expect(result.config).toEqual({})
      expect(result.hostnames).toEqual([])
      expect(result.debug).toBe(false)
    })

    it("should generate empty config when no middleware options exist", () => {
      const result = hydrateGeneratedConfig(
        new Map<string, HostnameMiddlewareOptions>(),
      )

      expect(result.configString).toBe(`${header}export const config = {}
`)
      expect(result.config).toEqual({})
      expect(result.hostnames).toEqual([])
      expect(result.debug).toBe(false)
    })

    it("should include debug for the hostname that has it configured", () => {
      const middlewareOptionsMap = new Map<string, HostnameMiddlewareOptions>([
        ["app.example.com", { debug: true }],
        ["staging.example.com", { debug: false }],
      ])

      const { config, debug } = hydrateGeneratedConfig(middlewareOptionsMap)

      expect(config["app.example.com"].debug).toBe(true)
      expect(config["staging.example.com"].debug).toBe(false)
      expect(debug).toBe(true)
    })

    it("should handle debug supplied as a string", () => {
      const middlewareOptionsMap = new Map<string, HostnameMiddlewareOptions>([
        ["app.example.com", { debug: "true" }],
        ["staging.example.com", { debug: "false" }],
      ])

      const { config, debug } = hydrateGeneratedConfig(middlewareOptionsMap)

      expect(config["app.example.com"].debug).toBe(true)
      expect(config["staging.example.com"].debug).toBe(false)
      expect(debug).toBe(true)
    })

    it("should enable debug if ANY hostname has debug enabled", () => {
      const middlewareOptionsMap = new Map<string, HostnameMiddlewareOptions>([
        ["app.example.com", { debug: false }],
        ["staging.example.com", { debug: true }],
      ])

      expect(hydrateGeneratedConfig(middlewareOptionsMap).debug).toBe(true)
    })

    it("should default debug to false when not specified", () => {
      const middlewareOptionsMap = new Map<string, HostnameMiddlewareOptions>([
        ["app.example.com", {}],
      ])

      expect(hydrateGeneratedConfig(middlewareOptionsMap).debug).toBe(false)
    })
  })

  describe("extractHostnamesFromConfig", () => {
    it("should extract hostnames from config with a lock page only", () => {
      const config = {
        "app.example.com": { website: { lockPageSlug: "/maintenance" } },
      }

      expect(extractHostnamesFromConfig(config)).toEqual(["app.example.com"])
    })

    it("should extract hostnames from config with CSP only", () => {
      const config = {
        "app.example.com": {
          website: { cspMode: "enforced" as const },
        },
      }

      expect(extractHostnamesFromConfig(config)).toEqual(["app.example.com"])
    })

    it("should extract all hostnames from config with multiple hostnames", () => {
      const config = {
        "app.example.com": {
          website: {
            lockPageSlug: "/maintenance",
            cspMode: "enforced" as const,
          },
        },
        "staging.example.com": {
          website: { cspMode: "report-only" as const },
        },
      }

      const hostnames = extractHostnamesFromConfig(config)
      expect(hostnames).toContain("app.example.com")
      expect(hostnames).toContain("staging.example.com")
      expect(hostnames).toHaveLength(2)
    })

    it("should return empty array for empty config", () => {
      expect(extractHostnamesFromConfig({})).toEqual([])
    })
  })
})
